import{_ as d,I as l,c as g,o as a,a5 as n,b as i,w as t,a as r,J as s,a6 as c}from"./chunks/framework.BmNIwhaK.js";const b=JSON.parse('{"title":"SyncSeries Unified Architecture and Module Integration","description":"Enterprise architecture overview detailing how the 11 SyncSeries domain modules, SyncSDK, and 6 shared foundation modules integrate across a 4-tier architecture using standard REST and MCP protocols","frontmatter":{"title":"SyncSeries Unified Architecture and Module Integration","shortTitle":"Ecosystem Overview","category":"Getting Started","sort":1,"description":"Enterprise architecture overview detailing how the 11 SyncSeries domain modules, SyncSDK, and 6 shared foundation modules integrate across a 4-tier architecture using standard REST and MCP protocols","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/en/ecosystem/"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/ecosystem/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/ecosystem/"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/ecosystem/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/ecosystem/"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"SyncSeries Unified Architecture and Module Integration | Empasy Docs"}],["meta",{"property":"og:description","content":"Enterprise architecture overview detailing how the 11 SyncSeries domain modules, SyncSDK, and 6 shared foundation modules integrate across a 4-tier architecture using standard REST and MCP protocols"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/ecosystem/"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"SyncSeries Unified Architecture and Module Integration | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Enterprise architecture overview detailing how the 11 SyncSeries domain modules, SyncSDK, and 6 shared foundation modules integrate across a 4-tier architecture using standard REST and MCP protocols"}]]},"headers":[],"relativePath":"en/ecosystem/index.md","filePath":"en/ecosystem/index.md","lastUpdated":1795293539000}'),p={name:"en/ecosystem/index.md"};function u(h,e,y,m,S,f){const o=l("Mermaid");return a(),g("div",null,[e[2]||(e[2]=n('<h1 id="syncseries-unified-architecture-and-module-integration" tabindex="-1">SyncSeries Unified Architecture and Module Integration <a class="header-anchor" href="#syncseries-unified-architecture-and-module-integration" aria-label="Permalink to “SyncSeries Unified Architecture and Module Integration”">​</a></h1><blockquote><p><strong>Reader&#39;s Guide</strong>: This document is a technical overview for developers and system architects. For a non-technical service introduction, visit the <a href="https://empasy.io/en/pages/index.html" target="_blank" rel="noreferrer">Empasy Official Website (empasy.io)</a>. For installation-free hands-on demos, visit the <a href="https://sync.empasy.io/en/" target="_blank" rel="noreferrer">Unified Demo Portal (sync.empasy.io)</a>. For adoption proposal PDFs, see the <a href="/en/proposals/">Proposal Repository (/en/proposals/)</a>, and for core technical term definitions, refer to the <a href="/en/glossary/">Enterprise Technical Glossary (/en/glossary/)</a>.</p></blockquote><h2 id="_1-architecture-overview-and-design-principles" tabindex="-1">1. Architecture Overview and Design Principles <a class="header-anchor" href="#_1-architecture-overview-and-design-principles" aria-label="Permalink to “1. Architecture Overview and Design Principles”">​</a></h2><p><strong>SyncSeries</strong> reorganizes traditional IT landscapes—where individual software applications operated as isolated silos—into a <strong>modular A2A (Agent-to-Agent) operating architecture</strong> in which domain modules communicate and collaborate through standard protocols on top of a shared back-office, authentication, and auditing foundation.</p><p>Core enterprise services and shared modules run on a single standardized technology stack comprising <strong>Java 25</strong>, <strong>Spring Boot 4.0</strong>, <strong>AgentScope Java (<code>io.agentscope:agentscope-harness:2.0.2</code>)</strong>, and <strong>PostgreSQL 18.6 (<code>pgvector</code>)</strong>, following three foundational design principles:</p><ol><li><strong>Centralized Orchestration</strong>: <strong>SyncVerse</strong>, the central control tower module, analyzes business requests, decomposes them into sub-tasks, and delegates execution to the appropriate domain modules.</li><li><strong>Standardized Interface Interoperability</strong>: Every module exposes and invokes tools and APIs conforming to the <strong><a href="/en/glossary/#mcp">Model Context Protocol (MCP)</a></strong> and the enterprise-wide single <strong><a href="/en/glossary/#canonical-url">Canonical URL</a></strong> (<code>/api/v1/{product}/...</code>) specification.</li><li><strong>Pre-Execution Approval and Recovery Safety</strong>: High-risk operations such as data mutations, schema changes, and code deployments pass through <strong><a href="/en/glossary/#hitl">Multi-Party HITL (Human-in-the-Loop)</a></strong> approval gates and <strong>snapshot-based compensating transactions</strong> to guarantee data consistency and rollback availability.</li></ol><hr><h2 id="_2-4-tier-enterprise-architecture-and-core-module-composition" tabindex="-1">2. 4-Tier Enterprise Architecture and Core Module Composition <a class="header-anchor" href="#_2-4-tier-enterprise-architecture-and-core-module-composition" aria-label="Permalink to “2. 4-Tier Enterprise Architecture and Core Module Composition”">​</a></h2><p>SyncSeries consists of 11 enterprise modules organized across four tiers by role and responsibility (<code>SyncVerse</code>, <code>SyncInsight</code>, <code>SyncLLM</code>, <code>SyncAPIM</code>, <code>SyncWatch</code>, <code>SyncBoot</code>, <code>SyncCMS</code>, <code>SyncShop</code>, <code>SyncOps</code>, <code>SyncETA</code>, <code>SyncCrawl</code>), a coding engine integration SDK (<code>SyncSDK</code>), and 6 shared foundation modules (<code>sync-core</code>, <code>sync-module-ai</code>, <code>sync-module-nl2sql</code>, <code>sync-module-audit</code>, <code>sync-module-deploy</code>, <code>sync-module-rag</code>).</p>',9)),(a(),i(c,null,{default:t(()=>[s(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20Tier1%20%5B%22Tier%201%3A%20Central%20Control%20%26%20Unified%20Orchestration%22%5D%0A%20%20%20%20%20%20%20%20SV%5B%22SyncVerse%20(A2A%20Control%20Tower%20%2F%20SyncETA%20QA%20%26%20SyncCrawl%20Integration)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Tier2%20%5B%22Tier%202%3A%20Decision%20Intelligence%2C%20Gateway%20%26%20Security%20Observability%22%5D%0A%20%20%20%20%20%20%20%20SI%5B%22SyncInsight%20(Decision%20Intelligence)%22%5D%0A%20%20%20%20%20%20%20%20SLLM%5B%22SyncLLM%20(AI%20Gateway%20%26%20FinOps)%22%5D%0A%20%20%20%20%20%20%20%20SAPIM%5B%22SyncAPIM%20(API%20Security%20%26%20Governance)%22%5D%0A%20%20%20%20%20%20%20%20SWATCH%5B%22SyncWatch%20(Threat%20Intelligence%20%26%20Dual%20Rule%20Compiler)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Tier3%20%5B%22Tier%203%3A%20Specialized%20Domain%20Module%20Suite%22%5D%0A%20%20%20%20%20%20%20%20SB%5B%22SyncBoot%20(Backend%20Foundation)%22%5D%0A%20%20%20%20%20%20%20%20SCMS%5B%22SyncCMS%20(Content%20Swarm%20%26%20AEO%2FGEO)%22%5D%0A%20%20%20%20%20%20%20%20SSHOP%5B%22SyncShop%20(8-Service%20Commerce%20MSA)%22%5D%0A%20%20%20%20%20%20%20%20SOPS%5B%22SyncOps%20(SI%20PMO%20%26%20Profit%2FCompliance)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Tier4%20%5B%22Tier%204%3A%20Coding%20Integration%20SDK%20%26%206%20Shared%20Foundation%20Modules%22%5D%0A%20%20%20%20%20%20%20%20SDK%5B%22SyncSDK%20(Multi-Engine%20Coding%20SPI)%22%5D%0A%20%20%20%20%20%20%20%20CORE%5B%22sync-core%20%26%20sync-module-ai%2Faudit%2Fnl2sql%2Fdeploy%2Frag%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20SV%20%3C--%3E%20%7C%22MCP%20%2F%20MsgHub%22%7C%20Tier2%0A%20%20%20%20SV%20%3C--%3E%20%7CA2A%20Task%20Delegation%7C%20Tier3%0A%20%20%20%20SV%20--%3E%20%7CSpec-First%20Code%20Mutation%7C%20Tier4%0A%20%20%20%20Tier3%20--%3E%20%7CUnified%20LLM%20Proxy%7C%20SLLM%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=n('<h3 id="tier-1-central-control-unified-orchestration-layer" tabindex="-1">Tier 1: Central Control &amp; Unified Orchestration Layer <a class="header-anchor" href="#tier-1-central-control-unified-orchestration-layer" aria-label="Permalink to “Tier 1: Central Control &amp; Unified Orchestration Layer”">​</a></h3><ul><li><strong>SyncVerse (<code>sync-verse</code>)</strong>: The central orchestration layer of the ecosystem. It provides unified governance over 5-Step Spec Studio-based specification and task tracking, multi-coding-engine SPI routing (<code>CodingAgentRoutingProxy</code>), multi-party HITL approvals, web/mobile QA (<code>SyncETA</code>), and web data collection (<code>SyncCrawl</code>).</li></ul><h3 id="tier-2-decision-intelligence-ai-gateway-security-observability-layer" tabindex="-1">Tier 2: Decision Intelligence, AI Gateway &amp; Security Observability Layer <a class="header-anchor" href="#tier-2-decision-intelligence-ai-gateway-security-observability-layer" aria-label="Permalink to “Tier 2: Decision Intelligence, AI Gateway &amp; Security Observability Layer”">​</a></h3><ul><li><strong>SyncInsight (<code>sync-insight</code>)</strong>: Collects and analyzes heterogeneous internal and external data, generating evidence-based reports and actionable proposals via 2-Phase Deep Research and Apache Calcite-powered read-only Safe <a href="/en/glossary/#nl2sql">NL2SQL</a>.</li><li><strong>SyncLLM (<code>sync-llm</code>)</strong>: Dedicated to multi-LLM tier routing, real-time PII masking, Redis <a href="/en/glossary/#semantic-cache">Semantic Cache</a>, and department-level <a href="/en/glossary/#finops">FinOps</a> budget guardrails.</li><li><strong>SyncAPIM (<code>sync-apim</code>)</strong>: Built on a 4-independent-JVM architecture (<code>admin</code>, <code>receiver</code>, <code>detector</code>, <code>gateway</code>), it identifies unregistered shadow APIs, diagnoses OpenAPI 3.0.1 specification drift, detects six major categories of web/API attacks (<a href="/en/glossary/#waf">WAF</a> / <a href="/en/glossary/#ebpf">eBPF</a>), and performs dynamic masking across eight sensitive data categories.</li><li><strong>SyncWatch (<code>sync-watch</code>)</strong>: Collects and normalizes eight global security threat feeds (OSV.dev, GitHub GHSA, NVD CVE, CISA KEV, Nuclei, OWASP CRS, MITRE ATT&amp;CK, KISA) and diagnostic advisories (<a href="/en/glossary/#cvss-cve-stix">CVSS/CVE/STIX</a>), distributing security inspection and defense rules to <code>SyncVerse</code> (<code>VerseAuditPack</code>) and <code>SyncAPIM</code> (<code>ApimDefensePack</code>).</li></ul><h3 id="tier-3-specialized-domain-execution-layer" tabindex="-1">Tier 3: Specialized Domain Execution Layer <a class="header-anchor" href="#tier-3-specialized-domain-execution-layer" aria-label="Permalink to “Tier 3: Specialized Domain Execution Layer”">​</a></h3><ul><li><strong>SyncBoot (<code>sync-boot</code>)</strong>: The enterprise back-office standard foundation providing DB single-source-of-truth dynamic routing (<code>sys_permission</code>, <a href="/en/glossary/#rbac">RBAC</a>), zero-downtime configuration hot-swap (<code>sys_config</code>), and remote socket diagnostics.</li><li><strong>SyncCMS (<code>sync-cms</code>)</strong>: A hybrid headless CMS featuring Nuxt 3 SSR, a 3-stage Copywriter-SEO-Publisher content workflow, and SEO/AEO/GEO web quality inspection tools.</li><li><strong>SyncShop (<code>sync-shop</code>)</strong>: An e-commerce platform composed of eight independent microservices (<a href="/en/glossary/#msa">MSA</a>)—Gateway, Auth, Admin, Portal, Search, Monitor, MBG, and MCP Server—along with the storefront (<code>SYNC SELECT</code>).</li><li><strong>SyncOps (<code>sync-ops</code>)</strong>: Manages SI project profit and loss (contract rate vs. actual input cost), KOSA-grade personnel matrices, four types of performance guarantee bond expirations, subcontractor payment due-date monitoring, and Tax Special Treatment Act SHA-256 electronic research notes.</li></ul><h3 id="tier-4-coding-integration-sdk-6-shared-foundation-modules" tabindex="-1">Tier 4: Coding Integration SDK &amp; 6 Shared Foundation Modules <a class="header-anchor" href="#tier-4-coding-integration-sdk-6-shared-foundation-modules" aria-label="Permalink to “Tier 4: Coding Integration SDK &amp; 6 Shared Foundation Modules”">​</a></h3><ul><li><strong>SyncSDK (<code>sync-sdk</code>)</strong>: A development SDK that swaps CLI/coding agent adapters in a pluggable manner to match corporate policies via the <code>ICodingAgentClient</code> standard SPI and integrates a 4-Cycle build verification and recovery pipeline.</li><li><strong>6 Shared Modules</strong>: <code>sync-core</code>, <code>sync-module-ai</code>, <code>sync-module-nl2sql</code>, <code>sync-module-audit</code>, <code>sync-module-deploy</code>, and <code>sync-module-rag</code>.</li></ul><hr><h2 id="_3-agent-collaboration-lifecycle" tabindex="-1">3. Agent Collaboration Lifecycle <a class="header-anchor" href="#_3-agent-collaboration-lifecycle" aria-label="Permalink to “3. Agent Collaboration Lifecycle”">​</a></h2>',10)),(a(),i(c,null,{default:t(()=>[s(o,{id:"mermaid-121",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20Admin%20as%20Administrator%20%2F%20Business%20User%0A%20%20%20%20participant%20SV%20as%20SyncVerse%20(Control%20Tower)%0A%20%20%20%20participant%20SLLM%20as%20SyncLLM%20(Gateway)%0A%20%20%20%20participant%20SI%20as%20SyncInsight%20(Decision%20Intelligence)%0A%20%20%20%20participant%20SB%20as%20SyncBoot%20%2F%20SyncShop%20(Domain)%0A%20%20%20%20participant%20QA%20as%20SyncVerse%20QA%20(Regression%20Testing)%0A%0A%20%20%20%20Admin-%3E%3ESV%3A%20%22Apply%20new%20customer%20membership%20tier%20system%20and%20promotions%22%0A%20%20%20%20SV-%3E%3ESLLM%3A%20Request%20intent%20analysis%20and%20sub-task%20decomposition%0A%20%20%20%20SLLM--%3E%3ESV%3A%20Return%20%5BAnalysis%2C%20Domain%20Mutation%2C%20Test%20Verification%5D%20DAG%0A%20%20%20%20%0A%20%20%20%20SV-%3E%3ESI%3A%20Request%20membership%20criteria%20feasibility%20and%20margin%20simulation%0A%20%20%20%20SI--%3E%3ESV%3A%20Optimal%20discount%20rate%20and%20What-If%20simulation%20complete%0A%20%20%20%20%0A%20%20%20%20SV-%3E%3ESB%3A%20Delegate%20domain%20data%20snapshot%20backup%20and%20mutation%0A%20%20%20%20SB--%3E%3ESV%3A%20Pre-change%20snapshot%20preserved%20and%20preview%20ready%0A%20%20%20%20%0A%20%20%20%20SV-%3E%3EQA%3A%20Request%20E2E%20scenario%20generation%20and%20regression%20verification%0A%20%20%20%20QA--%3E%3ESV%3A%20All%20test%20cases%20passed%20(Pass%20Rate%3A%20100%25)%0A%20%20%20%20%0A%20%20%20%20SV-%3E%3EAdmin%3A%20%5BHITL%20Gate%5D%20Request%20final%20approval%20for%20production%20rollout%0A%20%20%20%20Admin-%3E%3ESV%3A%20Approve%0A%20%20%20%20SV-%3E%3ESB%3A%20Commit%20production%20transaction%20and%20apply%20with%20zero%20downtime%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=n('<hr><h2 id="_4-architectural-comparison-siloed-build-vs-syncseries-unified-architecture" tabindex="-1">4. Architectural Comparison (Siloed Build vs. SyncSeries Unified Architecture) <a class="header-anchor" href="#_4-architectural-comparison-siloed-build-vs-syncseries-unified-architecture" aria-label="Permalink to “4. Architectural Comparison (Siloed Build vs. SyncSeries Unified Architecture)”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Area</th><th style="text-align:left;">Siloed / Distributed System Operation</th><th style="text-align:left;">SyncSeries Shared-Foundation Unified Architecture</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>New Features &amp; API Expansion</strong></td><td style="text-align:left;">Authentication, authorization, logging, and auditing re-implemented per project</td><td style="text-align:left;">Reuses <code>SyncBoot</code> foundation, Canonical URLs (<code>/api/v1/{product}/*</code>), and 6 shared modules</td></tr><tr><td style="text-align:left;"><strong>Change Deployment &amp; Recovery</strong></td><td style="text-align:left;">Manual DB backups and manual log tracing/rollback upon incidents</td><td style="text-align:left;">Pre-change snapshot preservation, multi-party HITL approval gates, compensating-transaction rollback</td></tr><tr><td style="text-align:left;"><strong>LLM Cost &amp; Model Governance</strong></td><td style="text-align:left;">Separate API keys per team causing duplicate calls and untracked spend</td><td style="text-align:left;">Routed through single <code>SyncLLM</code> gateway with semantic caching and departmental FinOps quota policies</td></tr><tr><td style="text-align:left;"><strong>Regression Verification Automation</strong></td><td style="text-align:left;">Missed pre-deployment manual checks and broken scripts on UI changes</td><td style="text-align:left;"><code>SyncETA</code> scenario-driven automated execution with semantic DOM and vision-based self-healing</td></tr><tr><td style="text-align:left;"><strong>Security &amp; Audit Evidence</strong></td><td style="text-align:left;">Manual code reviews; delayed visibility into API inventory and data leaks</td><td style="text-align:left;">Threat rule distribution via <code>SyncAPIM</code> and <code>SyncWatch</code>, PII masking, and complete audit ledger logging</td></tr></tbody></table><hr><h2 id="_5-next-steps" tabindex="-1">5. Next Steps <a class="header-anchor" href="#_5-next-steps" aria-label="Permalink to “5. Next Steps”">​</a></h2><ul><li><strong><a href="/en/glossary/">Enterprise Technical Glossary</a></strong>: Official Single Source of Truth (SSOT) definitions for core SyncSeries technical terminology</li><li><strong><a href="/en/ecosystem/mcp-protocol">Standard MCP Protocol Specification</a></strong>: Inter-agent tool invocation and messaging standards</li><li><strong><a href="/en/ecosystem/agentscope-guide">AgentScope Java Standard Guide</a></strong>: Spring Boot 4.0 &amp; Java 25 backend agent development standards</li><li><strong><a href="/en/ecosystem/shared-modules-and-sdk">Shared Modules &amp; SDK Architecture</a></strong>: Structure of the 6 shared modules (<code>sync-core</code>, <code>sync-module-*</code>) and <code>SyncSDK</code></li><li><strong><a href="/en/ecosystem/e2e-workflow">End-to-End Workflow in Practice</a></strong>: Cross-module integration procedures based on real-world scenarios</li><li><strong><a href="/en/ecosystem/hitl-governance">HITL Governance &amp; Saga</a></strong>: Administrator safety approvals and distributed rollback mechanisms</li><li><strong><a href="/en/ecosystem/security-and-compliance">Security Whitepaper &amp; Compliance</a></strong>: Zero Data Retention and air-gapped security architecture</li><li><strong><a href="/en/proposals/">Product Brochures &amp; Proposal PDFs</a></strong>: Document repository for evaluation and enterprise proposals</li></ul>',6))])}const v=d(p,[["render",u]]);export{b as __pageData,v as default};
